CREATE DATABASE IF NOT EXISTS b4_class CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE b4_class;
CREATE TABLE IF NOT EXISTS students(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_code VARCHAR(40) NOT NULL UNIQUE,official_name VARCHAR(255) NOT NULL,display_name VARCHAR(120) NOT NULL,class_name VARCHAR(20) NOT NULL DEFAULT 'B4',specialization VARCHAR(120) NOT NULL DEFAULT 'Telecommunication',avatar_url VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS teachers(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,teacher_code VARCHAR(40) UNIQUE,official_name VARCHAR(255) NOT NULL,display_name VARCHAR(120) NOT NULL,class_name VARCHAR(20) NOT NULL DEFAULT 'B4',avatar_url VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id INT UNSIGNED NULL,teacher_id INT UNSIGNED NULL,official_name VARCHAR(255) NOT NULL,display_name VARCHAR(120) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('STUDENT','TEACHER','ADMIN','SUPER_ADMIN') NOT NULL DEFAULT 'STUDENT',status ENUM('ACTIVE','SUSPENDED','DISABLED') NOT NULL DEFAULT 'ACTIVE',avatar_url VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_user_student FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE SET NULL,CONSTRAINT fk_user_teacher FOREIGN KEY(teacher_id) REFERENCES teachers(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS permissions(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(80) NOT NULL UNIQUE,label VARCHAR(160) NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions(role ENUM('STUDENT','TEACHER','ADMIN','SUPER_ADMIN') NOT NULL,permission_id INT UNSIGNED NOT NULL,PRIMARY KEY(role,permission_id),FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS activation_keys(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,key_hash CHAR(64) NOT NULL UNIQUE,key_preview VARCHAR(30) NOT NULL,person_type ENUM('STUDENT','TEACHER') NOT NULL,student_id INT UNSIGNED NULL,teacher_id INT UNSIGNED NULL,official_name VARCHAR(255) NOT NULL,status ENUM('ACTIVE','USED','REVOKED','EXPIRED') NOT NULL DEFAULT 'ACTIVE',created_by BIGINT UNSIGNED NULL,used_user_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NULL,used_at DATETIME NULL,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE SET NULL,FOREIGN KEY(teacher_id) REFERENCES teachers(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(used_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS subjects(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,class_name VARCHAR(20) NOT NULL DEFAULT 'B4',teacher_name VARCHAR(160),progress TINYINT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS schedule(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,class_name VARCHAR(20) NOT NULL DEFAULT 'B4',day_order TINYINT UNSIGNED NOT NULL,day_name VARCHAR(30) NOT NULL,p1 VARCHAR(160),p2 VARCHAR(160),p3 VARCHAR(160),p4 VARCHAR(160),UNIQUE KEY uq_schedule_day(class_name,day_order)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS assignments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,description TEXT,status ENUM('OPEN','DONE','CLOSED') DEFAULT 'OPEN',subject_id INT UNSIGNED NULL,class_name VARCHAR(20) NOT NULL DEFAULT 'B4',due_at DATETIME NULL,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS assignment_submissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,assignment_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,content TEXT,file_url VARCHAR(500),status ENUM('SUBMITTED','GRADED') DEFAULT 'SUBMITTED',score DECIMAL(6,2),submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(assignment_id) REFERENCES assignments(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,UNIQUE KEY uq_submission(assignment_id,user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS grades(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,subject_id INT UNSIGNED NULL,grade_type VARCHAR(80) NOT NULL,score DECIMAL(7,2) NOT NULL,max_score DECIMAL(7,2) NOT NULL DEFAULT 100,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS attendance(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,date DATE NOT NULL,status ENUM('PRESENT','ABSENT','LATE','EXCUSED') NOT NULL,marked_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(marked_by) REFERENCES users(id) ON DELETE SET NULL,UNIQUE KEY uq_attendance(user_id,date)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS announcements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(220) NOT NULL,body TEXT NOT NULL,category VARCHAR(60) DEFAULT 'General',class_name VARCHAR(20) NOT NULL DEFAULT 'B4',created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS chat_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,body TEXT NOT NULL,reply_to_id BIGINT UNSIGNED NULL,file_url VARCHAR(500),deleted_at DATETIME NULL,deleted_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(reply_to_id) REFERENCES chat_messages(id) ON DELETE SET NULL,FOREIGN KEY(deleted_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS linked_accounts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,provider ENUM('GOOGLE','DISCORD','FACEBOOK') NOT NULL,provider_user_id VARCHAR(255) NOT NULL,provider_email VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_provider(provider,provider_user_id),UNIQUE KEY uq_user_provider(user_id,provider),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,title VARCHAR(220) NOT NULL,body TEXT,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS security_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_user_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,details TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS activity_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_user_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,entity_type VARCHAR(80),entity_id BIGINT UNSIGNED,details TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ai_conversations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(200),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ai_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,conversation_id BIGINT UNSIGNED NOT NULL,role ENUM('USER','ASSISTANT') NOT NULL,content TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(conversation_id) REFERENCES ai_conversations(id) ON DELETE CASCADE) ENGINE=InnoDB;
INSERT IGNORE INTO permissions(code,label) VALUES('MANAGE_ACCOUNTS','Manage accounts'),('MANAGE_KEYS','Manage activation keys'),('MANAGE_STUDENTS','Manage students'),('MANAGE_ROLES','Manage roles'),('MANAGE_SUBJECTS','Manage subjects'),('MANAGE_SCHEDULE','Manage schedule'),('MANAGE_ASSIGNMENTS','Manage assignments'),('MANAGE_EXAMS','Manage exams'),('MANAGE_GRADES','Manage grades'),('MANAGE_ATTENDANCE','Manage attendance'),('MANAGE_ANNOUNCEMENTS','Manage announcements'),('MANAGE_CHAT','Moderate chat'),('VIEW_LOGS','View security/activity logs'),('USE_AI','Use B4 AI'),('VIEW_CLASS','View class');
INSERT IGNORE INTO role_permissions(role,permission_id) SELECT 'SUPER_ADMIN',id FROM permissions;
INSERT IGNORE INTO role_permissions(role,permission_id) SELECT 'TEACHER',id FROM permissions WHERE code IN('MANAGE_SUBJECTS','MANAGE_ASSIGNMENTS','MANAGE_EXAMS','MANAGE_GRADES','MANAGE_ATTENDANCE','MANAGE_ANNOUNCEMENTS','MANAGE_CHAT','USE_AI','VIEW_CLASS');
INSERT IGNORE INTO role_permissions(role,permission_id) SELECT 'ADMIN',id FROM permissions WHERE code IN('MANAGE_STUDENTS','MANAGE_SUBJECTS','MANAGE_SCHEDULE','MANAGE_ASSIGNMENTS','MANAGE_EXAMS','MANAGE_ANNOUNCEMENTS','MANAGE_CHAT','VIEW_LOGS','USE_AI','VIEW_CLASS');
INSERT IGNORE INTO role_permissions(role,permission_id) SELECT 'STUDENT',id FROM permissions WHERE code IN('USE_AI','VIEW_CLASS');
